          ng_chat: "Ứng dụng chat", ng_push: "Thông báo đẩy lên điện thoại", ng_other: "Khác", npOn: "Nhận được trên:", np_ios: "iPhone", np_android: "Android", np_web: "Web / máy tính", npIos: "Có trên iPhone", npLegend: "= có app iPhone", npNoIos: "không có app iPhone", npWebhook: "Gửi JSON tới máy chủ hoặc hệ thống tự động hoá của bạn (Home Assistant, n8n, Node-RED…).", nf_access_token: "Access Token", nf_room_id: "Room ID", nf_number: "Số gửi (đã đăng ký trong signal-cli)", nf_recipients: "Người nhận (số điện thoại hoặc ID nhóm, cách nhau dấu phẩy)", nf_device_key: "Device Key", nf_user_key: "User Key", nf_host: "Máy chủ SMTP", nf_port: "Cổng", nf_security: "Bảo mật", nf_username: "Tên đăng nhập", nf_password: "Mật khẩu / mật khẩu ứng dụng", nf_sender: "Người gửi", nf_to: "Gửi tới (cách nhau dấu phẩy)", nf_urls: "Apprise URL", nf_key: "Khoá cấu hình", nopt_starttls: "STARTTLS (cổng 587)", nopt_ssl: "SSL/TLS (cổng 465)", nopt_none: "Không (cổng 25, chỉ trong LAN)", nh_slack: "Slack → Apps → Incoming Webhooks → Add to Slack → chọn kênh → sao chép Webhook URL.", nh_teams: "Kênh Teams → ⋯ → Workflows → \"Post to a channel when a webhook request is received\" → sao chép URL (Office 365 connector đã ngừng).", nh_googlechat: "Không gian Google Chat → Ứng dụng và tích hợp → Webhook → Thêm webhook → sao chép URL (tài khoản Google Workspace).", nh_mattermost: "Mattermost → Integrations → Incoming Webhooks → Add → chọn kênh → sao chép URL. Webhook vào của Rocket.Chat cũng dùng được ở đây.", nh_matrix: "Nên dùng tài khoản bot: Element → Cài đặt → Trợ giúp & Giới thiệu → Access Token (hoặc đăng nhập qua API). Mời bot vào phòng; Room ID ở Cài đặt phòng → Nâng cao.", nh_signal: "Cần signal-cli-rest-api (bbernhard/signal-cli-rest-api) chạy bằng Docker với một số đã đăng ký. Máy chủ = địa chỉ của nó.", nh_bark: "Chỉ cho iPhone: cài Bark từ App Store, sao chép key trong đường dẫn (https://api.day.app/<key>/…). Để trống máy chủ để dùng api.day.app hoặc dùng máy chủ Bark riêng.", nh_pushover: "pushover.net: User Key ở trang chính; tạo Application để lấy API Token. Có app iPhone, Android và máy tính (mua một lần).", nh_pushbullet: "pushbullet.com → Settings → Account → Create Access Token. Chủ yếu cho Android và trình duyệt.", nh_email: "Gmail / Outlook: dùng mật khẩu ứng dụng (bật xác minh 2 bước). Gmail: smtp.gmail.com, STARTTLS 587. Outlook: smtp-mail.outlook.com, STARTTLS 587.", nh_apprise: "Apprise API (caronc/apprise chạy bằng Docker) gửi tới hơn 100 dịch vụ: WhatsApp, LINE, SMS, Rocket.Chat, Home Assistant… Nhập Apprise URL, hoặc khoá của cấu hình đã lưu trong Apprise.",
          setServers: "Máy chủ", setServersDesc: "Quản lý AppManager trên máy khác", svCount: "{n} máy khác", svHowTitle: "Cách quản lý nhiều máy chủ hoạt động", svProto: "Giao thức", svProtoDesc: "AppManager này gọi REST API của AppManager trên máy kia qua HTTP hoặc HTTPS, xác thực bằng API Token (Authorization: Bearer). Không mở Docker socket ra mạng, không cần cài thêm gì.", svReq: "Yêu cầu", svReqDesc: "máy kia chạy AppManager 0.17.0 trở lên, và máy này truy cập được địa chỉ:cổng của nó (cùng mạng LAN, qua VPN như Tailscale / WireGuard, hoặc HTTPS qua reverse proxy).", svTok: "API Token", svTokDesc: "trên máy kia vào Cài đặt → API Token, tạo Token quyền \"Cập nhật\" (cập nhật, khởi động lại) hoặc \"Chỉ đọc\" (chỉ xem). Nên giới hạn Token chỉ cho IP của máy này.", svSec: "Bảo mật", svSecDesc: "qua Internet luôn dùng HTTPS — HTTP gửi Token không mã hoá. Token lưu trong database của máy này và không hiện lại.", svWork: "Ai làm việc", svWorkDesc: "máy kia vẫn tự tải bản mới, tạo lại container, kiểm tra sức khoẻ và tự quay lại; máy này chỉ gửi lệnh và hiện kết quả. Nhật ký hoạt động của cả hai máy đều ghi lại.", svAdd: "Thêm máy chủ", svEditTitle: "Sửa máy chủ", svListTitle: "Các máy chủ", svRecheck: "Kiểm tra lại", svChecking: "Đang kiểm tra…", svOffline: "Không kết nối được", svApps: "{n} app", svUpdates: "{n} bản mới", svHttp: "HTTP", svScope: "Quyền Token", svOpen: "Mở", svEdit: "Sửa", svDelete: "Gỡ", svNone: "Chưa có máy chủ nào khác.", svName: "Tên", svNamePh: "vd: NAS ở văn phòng", svUrl: "Địa chỉ AppManager của máy kia", svUrlHint: "Địa chỉ bạn vẫn mở AppManager đó trên trình duyệt, có cả cổng.", svToken: "API Token của máy kia", svTokenKeep: "Để trống = giữ Token đã lưu", svTokenHint: "Tạo trên máy kia: Cài đặt → API Token (quyền Cập nhật).", svVerify: "Kiểm tra chứng chỉ HTTPS", svVerifyDesc: "Chỉ tắt khi dùng chứng chỉ tự ký trong mạng bạn tin cậy.", svHttpWarn: "HTTP không mã hoá: chỉ dùng trong mạng nhà hoặc qua VPN. Qua Internet hãy dùng HTTPS.", svTest